from pathlib import Path
root=Path(__file__).resolve().parent.parent
p=root/'museum.js';s=p.read_text(encoding='utf-8')
start=s.index('  function merchFolder(');end=s.index('\n',s.index('  function merchDetail(',start))
new=r'''  let merchBrowse=null;
  const merchOptions=(values,placeholder)=>`<option value="">${placeholder}</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}`;
  function merchCards(r,folder,rows){return rows.map(({g,i})=>`<button class="file-card merch-card" data-merch-category="${esc(g.category)}" data-path="${filePath(r,folder,i)}"><div class="merch-card-image"><img src="${esc(g.image)}" alt="${esc(g.name)}商品图" loading="lazy" referrerpolicy="no-referrer" draggable="false"><span>${esc(g.category)}</span></div><strong>${esc(g.name)}</strong><span class="merch-price">${esc(g.price)}</span><small>${esc(g.characters||'系列商品')} · ${esc(g.releaseDate||'日期见详情')}</small><small>${g.channels.length} 个渠道</small><span class="merch-card-open">查看详情 →</span></button>`).join('');}
  function merchFolder(r,folder){const goods=r.merch,categories=[...new Set(goods.map(g=>g.category))], report=r.collectionReport;merchBrowse={r,folder,category:'全部',limit:48};return `<div class="merch-intro"><span>周边资料库 · ${goods.length.toLocaleString()} 个商品 / 系列</span><p>来源：${link('https://zutapoke.com/goodsdb/','学マス商品 DB')} · 整理于 ${esc(r.retrievedAt)}<br>${report?`数据库 ${report.databaseRows.toLocaleString()} 条原始记录，合并 ${report.mergedDuplicateRows} 条重复记录；另保留首批精选和娃娃汇总。`:'收录商品资料。'}<br>价格、发售月份按来源记录；库存与预约状态请在商店确认。新增图片由来源网站提供。</p></div><details class="merch-channel-summary"><summary>购买与资料渠道总览 <span>${r.channelSummary.length} 个渠道</span></summary><div class="merch-channel-list">${r.channelSummary.map(c=>`<div><strong>${esc(c.name)}</strong><p>${esc(c.description)} · ${esc(c.examples.join(' / '))}</p>${link(c.sourceUrl,'查看来源')}</div>`).join('')}</div></details><div class="merch-tools"><label>搜索商品<input id="merch-query" type="search" placeholder="商品名、角色、系列关键词" autocomplete="off"></label><label>角色<select id="merch-idol">${merchOptions([...new Set(goods.map(g=>g.characters).filter(Boolean))].sort(),'全部角色')}</select></label><label>原始类型<select id="merch-type">${merchOptions([...new Set(goods.map(g=>g.originalType).filter(Boolean))].sort(),'全部类型')}</select></label><label>渠道<select id="merch-shop">${merchOptions(r.channelSummary.map(c=>c.name),'全部渠道')}</select></label></div><nav class="merch-filters" aria-label="周边分类">${['全部',...categories].map(c=>`<button data-merch-filter="${esc(c)}" aria-pressed="${c==='全部'}">${esc(c)}${c==='全部'?'':` (${goods.filter(g=>g.category===c).length})`}</button>`).join('')}</nav><p class="merch-result" role="status">找到 ${goods.length.toLocaleString()} 个，已显示 ${Math.min(48,goods.length)} 个</p><div class="file-grid merch-grid">${merchCards(r,folder,goods.slice(0,48).map((g,i)=>({g,i})))}</div><button class="pill merch-more" data-merch-more ${goods.length<=48?'hidden':''}>继续加载 48 个商品 ↓</button>${r.articleIndex?`<details class="merch-articles"><summary>周边子页面情报索引 · ${r.articleIndex.length} 篇</summary><p>已读取周边分类全部 ${report.archivePages} 页。下面保留各文章的商品小标题和出处，可继续核对联名、特典和历史款。</p><label>搜索文章<input id="merch-article-query" type="search" placeholder="联名、系列、娃娃等"></label><div class="merch-article-list">${r.articleIndex.map(a=>`<details class="merch-article" data-article-search="${esc((a.title+' '+a.sections.join(' ')).toLowerCase())}"><summary>${esc(a.title)}</summary><p>${esc(a.sections.join(' / ')||'商品信息见来源文章')}</p>${link(a.url,'打开原文章')}</details>`).join('')}</div></details>`:''}`;}
  function updateMerch(reset=true){if(!merchBrowse)return;if(reset)merchBrowse.limit=48;const {r,folder,category,limit}=merchBrowse,q=($('merch-query')?.value||'').trim().toLowerCase(),idol=$('merch-idol')?.value,type=$('merch-type')?.value,shop=$('merch-shop')?.value;const rows=r.merch.map((g,i)=>({g,i})).filter(({g})=>(category==='全部'||g.category===category)&&(!q||(g.name+' '+(g.characters||'')+' '+(g.originalType||'')+' '+g.category).toLowerCase().includes(q))&&(!idol||g.characters===idol)&&(!type||g.originalType===type)&&(!shop||g.channels.some(c=>c.name===shop)));document.querySelector('.merch-grid').innerHTML=merchCards(r,folder,rows.slice(0,limit));document.querySelector('.merch-result').textContent=`找到 ${rows.length.toLocaleString()} 个，已显示 ${Math.min(limit,rows.length)} 个`;document.querySelector('[data-merch-more]').hidden=limit>=rows.length;document.querySelectorAll('[data-merch-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.merchFilter===category)));}
  function merchDetail(g){return `<div class="merch-detail"><button class="merch-photo" data-merch-image aria-label="放大周边图片"><img src="${esc(g.image)}" alt="${esc(g.name)}商品图" referrerpolicy="no-referrer"><span>点击放大 ↗</span></button><span class="eyebrow">${esc(g.category)} / 商品资料</span><p class="merch-detail-price">${esc(g.price)}</p><p>${esc(g.description)}</p><dl class="merch-facts">${[['角色',g.characters],['原始类型',g.originalType],['来源发售月份',g.releaseDate],['尺寸',g.size],['数据库编号',g.sourceRecordIds?.join(' / ')]].filter(x=>x[1]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${g.variants?.length?`<details class="merch-variants"><summary>同名记录的其他月份 / 价格</summary>${g.variants.map(v=>`<p>DB ${esc(v.sourceRecordId)} · ${esc(v.releaseDate||'日期未标注')} · ${esc(v.price||'价格未标注')}</p>`).join('')}</details>`:''}<div class="merch-buy"><h2>购买与资料链接</h2><p>${esc(g.availability)}</p>${g.channels.length?g.channels.map(c=>`<div class="merch-channel-row">${link(c.url,c.name,'pill')}<span>${esc(c.linkType||'来源商品链接')}</span></div>`).join(''):'<p>来源未列出渠道链接，保留商品档案供查阅。</p>'}</div><div class="merch-provenance"><p>资料整理：${esc(g.checkedAt)} · ${esc(g.sourceName)}</p>${link(g.sourceUrl,'查看汇总来源')}${g.verificationUrl?link(g.verificationUrl,'查看官方核对页面'):''}<p>来源商店链接可能包含联盟推广。图片为来源的商品示意图，版权归原权利人。本站不提供购买或实时库存查询。</p></div></div>`;}
  document.addEventListener('input',e=>{if(e.target.id==='merch-query')updateMerch();if(e.target.id==='merch-article-query'){const q=e.target.value.trim().toLowerCase();document.querySelectorAll('[data-article-search]').forEach(a=>a.hidden=!a.dataset.articleSearch.includes(q));}});
  document.addEventListener('change',e=>{if(['merch-idol','merch-type','merch-shop'].includes(e.target.id))updateMerch();});'''
s=s[:start]+new+s[end:]
start=s.index("    const merchFilter=e.target.closest('[data-merch-filter]')");end=s.index('\n',start)
s=s[:start]+"    const merchFilter=e.target.closest('[data-merch-filter]');if(merchFilter){merchBrowse.category=merchFilter.dataset.merchFilter;updateMerch();return;}if(e.target.closest('[data-merch-more]')){merchBrowse.limit+=48;updateMerch(false);return;}"+s[end:]
s=s.replace("querySelectorAll('button,a[href],summary,[tabindex=\"0\"]')","querySelectorAll('button,a[href],input,select,summary,[tabindex=\"0\"]')")
p.write_text(s,encoding='utf-8')
css=root/'museum.css'
with css.open('a',encoding='utf-8') as f:f.write('''\n.merch-tools{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:25px}.merch-tools label,.merch-articles label{font-size:11px;color:var(--soft)}.merch-tools input,.merch-tools select,.merch-articles input{display:block;width:100%;min-width:0;padding:11px 12px;margin-top:6px;border:1px solid var(--line);border-radius:5px;background:#fcfdf9;color:var(--ink)}.merch-tools label:first-child{grid-column:1/-1}.merch-tools label:last-child{grid-column:1/-1}.merch-more{display:block;margin:30px auto}.merch-facts{margin:24px 0;font-size:12px}.merch-facts>div{display:grid;grid-template-columns:100px 1fr;gap:15px;padding:12px 0;border-bottom:1px solid var(--line)}.merch-facts dt{color:var(--soft)}.merch-facts dd{margin:0;overflow-wrap:anywhere}.merch-channel-row{display:flex;align-items:center;gap:15px;margin:10px 0}.merch-channel-row .pill{margin:0}.merch-channel-row>span{font-size:10px;color:var(--soft)}.merch-articles{margin-top:40px;border-top:1px solid var(--line);padding-top:20px;font-size:12px}.merch-articles summary,.merch-variants summary{cursor:pointer}.merch-articles>p{font-size:11px;margin:16px 0;color:var(--soft)}.merch-article-list{margin-top:20px}.merch-article{border-bottom:1px solid var(--line);padding:12px 0;overflow-wrap:anywhere}.merch-article p{color:var(--soft);font-size:10px;margin:12px 0}.merch-article a{color:var(--accent);font-size:11px}.merch-variants{font-size:11px;margin:20px 0}.merch-card img{color:var(--soft);font-size:10px}.merch-grid small{display:block}.merch-articles input{margin-bottom:20px}\n''')
b=root/'tools/build-public.mjs';t=b.read_text(encoding='utf-8').replace('posters.add(goods.image);',"if (!/^https?:/.test(goods.image)) posters.add(goods.image);");b.write_text(t,encoding='utf-8')
v=root/'verify-museum-data.mjs';t=v.read_text(encoding='utf-8').replace("assert.equal(gakumas.merch.length,19,'首批周边商品 / 系列应为 19 个');","assert.equal(gakumas.collectionReport.databaseRows,5271);assert.equal(gakumas.collectionReport.articlesRead,279);assert.equal(gakumas.collectionReport.failures.length,0);assert.equal(new Set(gakumas.merch.map(g=>g.id)).size,gakumas.merch.length);assert.equal(gakumas.merch.filter(g=>g.sourceRecordIds).reduce((n,g)=>n+g.sourceRecordIds.length,0),5271);").replace("assert.equal(gakumas.channelSummary.length,12,'来源渠道应为 12 个');",'assert(gakumas.channelSummary.length>=40);').replace("assert(existsSync(resolve(root,g.image)),'周边图片不存在');assert(g.channels.length,'周边需要来源渠道');","assert(g.image.startsWith('https://')||existsSync(resolve(root,g.image)),'周边图片不存在');")
v.write_text(t,encoding='utf-8')
print('Updated searchable product UI, original deep links retained')
